before_meta:=jsonb_build_object('schemas',(select jsonb_agg(jsonb_build_array(nspname,pg_get_userbyid(nspowner),nspacl::text) order by nspname) from pg_namespace where nspname in ('private','judoju_control','public')),'relations',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,c.relkind,pg_get_userbyid(c.relowner),c.relacl::text,c.relrowsecurity,c.relforcerowsecurity,c.reloptions,case when c.relkind='v' then pg_get_viewdef(c.oid,true) else null end) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list')) and c.relkind in ('r','p','v','m','f','S')),'columns',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl::text,a.attcollation::regcollation::text,pg_get_expr(d.adbin,d.adrelid)) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list')) and a.attnum>0 and not a.attisdropped and c.relkind in ('r','p','v','m','f')),'constraints',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,x.conname,pg_get_constraintdef(x.oid,true)) order by n.nspname,c.relname,x.conname) from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list'))),'indexes',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,pg_get_indexdef(i.indexrelid)) order by n.nspname,c.relname,pg_get_indexdef(i.indexrelid)) from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list'))),'policies',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,p.polname,p.polpermissive,p.polcmd,p.polroles::text,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) order by n.nspname,c.relname,p.polname) from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list'))),'triggers',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list')) and not t.tgisinternal),'functions',(select jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),pg_get_userbyid(p.proowner),p.proacl::text,pg_get_functiondef(p.oid)) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('private','judoju_control','public') and p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),'types',(select jsonb_agg(jsonb_build_array(n.nspname,t.typname,t.typtype,pg_get_userbyid(t.typowner),t.typacl::text,(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid)) order by n.nspname,t.typname) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('private','judoju_control','public')),'sequences',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,s.seqtypid::regtype::text,s.seqstart,s.seqincrement,s.seqmax,s.seqmin,s.seqcache,s.seqcycle) order by n.nspname,c.relname) from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('private','judoju_control','public')),'defaults',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(d.defaclrole),coalesce(n.nspname,'GLOBAL'),d.defaclobjtype,d.defaclacl::text) order by pg_get_userbyid(d.defaclrole),coalesce(n.nspname,'GLOBAL'),d.defaclobjtype) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where d.defaclnamespace=0 or n.nspname in ('private','judoju_control','public')),'roles',(select jsonb_agg(jsonb_build_array(rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolconnlimit,rolvaliduntil,rolbypassrls,md5(coalesce(rolconfig::text,''))) order by rolname) from pg_roles),'memberships',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(roleid),pg_get_userbyid(member),pg_get_userbyid(grantor),admin_option,inherit_option,set_option) order by roleid,member,grantor) from pg_auth_members),'database_role_settings',(select jsonb_agg(jsonb_build_array(setdatabase,pg_get_userbyid(setrole),md5(setconfig::text)) order by setdatabase,setrole) from pg_db_role_setting where setdatabase=0 or setdatabase=(select oid from pg_database where datname=current_database())),'ddl_event_triggers',(select jsonb_agg(jsonb_build_array(e.evtname,e.evtevent,e.evtenabled,e.evttags,pg_get_userbyid(e.evtowner),n.nspname,p.proname,md5(pg_get_functiondef(p.oid))) order by e.evtname) from pg_event_trigger e join pg_proc p on p.oid=e.evtfoid join pg_namespace n on n.oid=p.pronamespace),'data',(select jsonb_agg(to_jsonb(r) order by relation) from (select 'judoju_control.environment_identity' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from judoju_control.environment_identity t union all select 'judoju_control.schema_artifacts' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from judoju_control.schema_artifacts t union all select 'private.adapters' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.adapters t union all select 'private.article_versions' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.article_versions t union all select 'private.audits' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.audits t union all select 'private.catalog_versions' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.catalog_versions t union all select 'private.checkpoints' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.checkpoints t union all select 'private.claims' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.claims t union all select 'private.companies' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.companies t union all select 'private.decisions' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n