8'),'sha256'),'hex') as digest from private.installations t union all select 'private.issue_aliases' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.issue_aliases t union all select 'private.issues' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.issues t union all select 'private.job_attempts' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.job_attempts t union all select 'private.jobs' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.jobs t union all select 'private.keyword_changes' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.keyword_changes t union all select 'private.keyword_definitions' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.keyword_definitions t union all select 'private.notification_deliveries' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.notification_deliveries t union all select 'private.outbox' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.outbox t union all select 'private.permission_profiles' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.permission_profiles t union all select 'private.policies' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.policies t union all select 'private.purge_tasks' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.purge_tasks t union all select 'private.ranking_entries' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.ranking_entries t union all select 'private.ranking_snapshots' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.ranking_snapshots t union all select 'private.runtime_identity' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.runtime_identity t union all select 'private.schedules' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.schedules t union all select 'private.sector_companies' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.sector_companies t union all select 'private.sectors' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.sectors t union all select 'private.source_documents' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.source_documents t union all select 'private.source_endpoint_links' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.source_endpoint_links t union all select 'private.source_revisions' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.source_revisions t union all select 'private.sources' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.sources t union all select 'private.stories' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.stories t union all select 'private.subgroups' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.subgroups t union all select 'private.view_aggregates' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.view_aggregates t union all select 'private.view_events' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from private.view_events t union all select 'public.news_public' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from public.news_public t) r));auth_before:=jsonb_build_object('guard','SOURCE_GUARD',
'auth_uid',(select jsonb_build_object('name','auth.uid','args',pg_get_function_identity_arguments(p.oid),'return_type',format_type(p.prorettype,null),'language',l.lanname,'volatility',p.provolatile,'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'strict',p.proisstrict,'config',p.proconfig,'definition',pg_get_functiondef(p.oid),'definition_sha256',encode(extensions.digest(convert_to(pg_get_functiondef(p.oid),'UTF8'),'sha256'),'hex'),'postgres_execute',has_function_privilege('postgres',p.oid,'EXECUTE'),'api_execute',(select jsonb_agg(jsonb_build_array(r,has_function_privilege(r,p.oid,'EXECUTE')) order by r collate "C") from unnest(array['anon','authenticated','service_role']) r),'effective_acl',(select jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) order by (case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end) collate "C",pg_get_userbyid(a.grantor) collate "C",a.privilege_type collate "C",a.is_grantable) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure('auth.uid()')),
'managed_tables',(select jsonb_agg(jsonb_build_array(cl.relname,pg_get_userbyid(cl.relowner),cl.relacl::text,cl.relrowsecurity,cl.relforcerowsecurity) order by cl.relname collate "C") from pg_class cl join pg_namespace n on n.oid=cl.relnamespace where n.nspname='auth' and cl.relname in ('users','sessions')),
'managed_columns',(select jsonb_agg(jsonb_build_array(cl.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl::text) order by cl.relname collate "C",a.attnum) from pg_attribute a join pg_class cl on cl.oid=a.attrelid join pg_namespace n on n.oid=cl.relnamespace where n.nspname='auth' and cl.relname in ('users','sessions') and a.attnum>0 and not a.attisdropped),
