if (select jsonb_agg(to_jsonb(x) order by version) from supabase_migrations.schema_migrations x) is distinct from '[{"name": "cloud02_dev_control", "version": "20261114000000", "statements": ["-- CLOUD02: DEV ONLY. Verify dashboard org and project before one execution.\n-- Expected org qfzgicohgpuogehdyzfx / project nxfpfvsdwbziowkxsxnh.\n-- No credentials, public objects, extensions, cron, or app data.\nbegin", "set local lock_timeout = ''2s''", "set local statement_timeout = ''15s''", "select pg_advisory_xact_lock(71002, 1)", "do $guard$\nbegin\n  if current_user <> ''postgres'' or current_database() <> ''postgres''\n     or not exists(select 1 from pg_roles where rolname=current_user and rolbypassrls) then\n    raise exception ''CLOUD02_ADMIN_TARGET_REQUIRED'';\n  end if;\n  if exists(select 1 from pg_namespace where nspname in (''private'',''judoju_control''))\n     or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace\n       where n.nspname=''public'' and c.relkind in (''r'',''p'',''v'',''m'',''f''))\n     or exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace\n       where n.nspname=''public'' and not exists(select 1 from pg_depend d\n         where d.classid=''pg_proc''::regclass and d.objid=p.oid and d.deptype=''e'')\n       and not (p.proname=''rls_auto_enable'' and p.pronargs=0\n         and p.prorettype=''event_trigger''::regtype and p.proowner=''postgres''::regrole)) then\n    raise exception ''CLOUD02_EMPTY_TARGET_REQUIRED'';\n  end if;\nend\n$guard$", "create schema judoju_control authorization postgres", "revoke all on schema judoju_control from public, anon, authenticated, service_role", "alter default privileges for role postgres in schema judoju_control revoke all on tables from public, anon, authenticated, service_role", "alter default privileges for role postgres in schema judoju_control revoke all on sequences from public, anon, authenticated, service_role", "alter default privileges for role postgres in schema judoju_control revoke execute on functions from public, anon, authenticated, service_role", "create table judoju_control.environment_identity (\n  singleton boolean primary key default true check(singleton),\n  product_id text not null check(product_id=''judoju-news''),\n  environment text not null check(environment=''dev''),\n  organization_ref text not null check(organization_ref=''qfzgicohgpuogehdyzfx''),\n  project_ref text not null check(project_ref=''nxfpfvsdwbziowkxsxnh''),\n  baseline_commit text not null check(baseline_commit=''94ac7e0c63d51cb646c9406992c26aafccaca0ef''),\n  stage text not null check(stage=''CLOUD02_CONTROL_ONLY''),\n  created_at timestamptz not null default now()\n)", "alter table judoju_control.environment_identity enable row level security", "alter table judoju_control.environment_identity force row level security", "revoke all on table judoju_control.environment_identity from public, anon, authenticated, service_role", "insert into judoju_control.environment_identity\n  (product_id,environment,organization_ref,project_ref,baseline_commit,stage)\nvalues (''judoju-news'',''dev'',''qfzgicohgpuogehdyzfx'',''nxfpfvsdwbziowkxsxnh'',\n  ''94ac7e0c63d51cb646c9406992c26aafccaca0ef'',''CLOUD02_CONTROL_ONLY'')", "commit"]}, {"name": "cloud03_dev_domain_foundation", "version": "20261114000001", "statements": ["-- New Judoju News local schema. No remote target, original article body or real user seed.\nbegin", "-- CLOUD03_GUARD_START: dev only, prior verified control identity required.\nset local lock_timeout=''2s''", "set local statement_timeout=''30s''", "select pg_advisory_xact_lock(71003,1)", "do $guard$\nbegin\n if current_user<>''postgres'' or current_database()<>''postgres''\n   or not exists(select 1 from pg_roles where rolname=current_user and rolbypassrls) then\n   raise exception ''CLOUD03_ADMIN_REQUIRED'';\n end if;\n if not exists(select 1 from pg_extension e join pg_namespace n on n.oid=e.extnamespace\n   where e.extname