create function public.get_public_article(p_issue uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare r jsonb;canonical uuid;
begin
 r:=public.resolve_issue(p_issue);if r->>'state'<>'PUBLISHED' then return r;end if;canonical:=(r->>'canonical_issue_id')::uuid;
 if exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id where i.id=canonical and v.public_body->>'_contract'='M1') and not private.m1_current_evidence(canonical) then return jsonb_build_object('state','CORRECTION_PENDING','message','근거·분류 재확인 중 · 기존 내용 제공 중지');end if;
 return private.m0_get_public_article_legacy(p_issue);
end$$;
create function private.m1_draft_shape(p_content jsonb) returns void language plpgsql immutable set search_path='' as $$
declare k text;x jsonb;y jsonb;
begin
 if p_content is null or jsonb_typeof(p_content)<>'object' or pg_column_size(p_content)>131072 then raise exception 'DRAFT_SHAPE_INVALID';end if;
 foreach k in array array['title','summary','article_kind','source_market','selection_market_basis','analysis_perspective','issue_analysis'] loop
   if jsonb_typeof(p_content->k) is distinct from 'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;
 end loop;
 if not p_content ? 'primary_sector_id' or jsonb_typeof(p_content->'primary_sector_id') not in ('string','null') then raise exception 'DRAFT_SHAPE_INVALID';end if;
 foreach k in array array['key_issues','risks','sources','impacts','scenarios','schedule'] loop
   if jsonb_typeof(p_content->k) is distinct from 'array' then raise exception 'DRAFT_SHAPE_INVALID';end if;
 end loop;
 for x in select value from jsonb_array_elements(p_content->'key_issues') union all select value from jsonb_array_elements(p_content->'risks') loop
   if jsonb_typeof(x)<>'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;
 end loop;
 for x in select value from jsonb_array_elements(p_content->'sources') loop
   if jsonb_typeof(x->'name') is distinct from 'string' or jsonb_typeof(x->'url') is distinct from 'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;
 end loop;
 for x in select value from jsonb_array_elements(p_content->'impacts') loop
   foreach k in array array['sector_id','path_id','direction','conditional_direction','description'] loop if jsonb_typeof(x->k) is distinct from 'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;end loop;
   foreach k in array array['conditions','evidence_ids'] loop
     if jsonb_typeof(x->k) is distinct from 'array' then raise exception 'DRAFT_SHAPE_INVALID';end if;
     for y in select value from jsonb_array_elements(x->k) loop if jsonb_typeof(y)<>'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;end loop;
   end loop;
 end loop;
 for x in select value from jsonb_array_elements(p_content->'scenarios') loop
   foreach k in array array['direction','title','expected_result'] loop if jsonb_typeof(x->k) is distinct from 'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;end loop;
   foreach k in array array['checks','path_ids'] loop
     if jsonb_typeof(x->k) is distinct from 'array' then raise exception 'DRAFT_SHAPE_INVALID';end if;
     for y in select value from jsonb_array_elements(x->k) loop if jsonb_typeof(y)<>'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;end loop;
   end loop;
 end loop;
 for x in select value from jsonb_array_elements(p_content->'schedule') loop
   foreach k in array array['kind','status','title','timezone','evidence_as_of'] loop if jsonb_typeof(x->k) is distinct from 'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;end loop;
   if x->>'kind'='EXACT' then
     if jsonb_typeof(x->'event_at') is distinct from 'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;
   elsif x->>'kind'='PERIOD' then
     foreach k in array array['period_label','period_start','period_end','precision'] loop if jsonb_typeof(x->k) is distinct from 'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;end loop;
   else raise exception 'DRAFT_SHAPE_INVALID';end if;
   if jsonb_typeof(x->'evidence_ids') is distinct from 'array' then raise exception 'DRAFT_SHAPE_INVALID';end if;
   for y in select value from jsonb_array_elements(x->'evidence_ids') loop if jsonb_typeof(y)<>'string' then raise exception 'DRAFT_SHAPE_INVALID';end if;end loop;
 end loop;
end$$;
create or replace function public.m1_save_draft(p_issue uuid,p_expected_revision bigint,p_content jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
begin perform private.m1_assert_editor();perform private.m1_draft_shape(p_content);
 perform 1 from private.issues where id=p_issue for update;
 return private.m1_save_draft_v1(p_issue,p_expected_revision,p_content);
end$$;
create function private.m1_independent_three(p_claim uuid) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from private.evidence_edges a
 join private.evidence_edges b on a.claim_id=b.claim_id and a.id<b.id
 join private.evidence_edges c on b.claim_id=c.claim_id and b.id<c.id
 where a.claim_id=p_claim
 and a.origin_verified and a.newsroom_verified and a.owner_group_verified and a.independent_fact_verified
 and b.origin_verified and b.newsroom_verified and b.owner_group_verified and b.independent_fact_verified
 and c.origin_verified and c.newsroom_verified and c.owner_group_verified and c.independent_fact_verified
 and a.origin_group_id<>b.origin_group_id and b.origin_group_id<>c.origin_group_id and a.origin_group_id<>c.origin_group_id
 and a.newsroom_id<>b.newsroom_id and b.newsroom_id<>c.newsroom_id and a.newsroom_id<>c.newsroom_id
 and a.owner_group_id<>b.owner_group_id and b.owner_group_id<>c.owner_group_id and a.owner_group_id<>c.owner_group_id)
$$;
create function private.m1_claim_allowed(p_claim uuid,p_issue uuid,p_macro boolean,p_official boolean) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from private.claims c where c.id=p_claim and c.issue_id=p_issue
 and c.verified and c.fact_current and c.korea_path_verified and c.claim_type<>'SENSITIVE_UNCONFIRMED'
 and (c.valid_until is null or c.valid_until>now())
 and (not p_official or c.official_original)
 and (not(p_macro or c.claim_type='SYSTEMIC_MACRO') or c.official_original or private.m1_independent_three(c.id)))
$$;
create function private.m1_core_evidence(p_issue uuid,p_kind text) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from private.claims where issue_id=p_issue)
 and not exists(select 1 from private.claims c where c.issue_id=p_issue and not private.m1_claim_allowed(c.id,p_issue,p_kind='MACRO',false))
$$;
alter function private.m1_prepare(uuid,jsonb,bigint,bigint) rename to m1_prepare_v4;
create function private.m1_prepare(p_issue uuid,p_input jsonb,p_policy bigint,p_catalog bigint) returns jsonb language plpgsql stable set search_path='' as $$
begin
 if not private.m1_core_evidence(p_issue,coalesce(p_input->>'article_kind','')) then raise exception 'CLAIM_NOT_VERIFIED';end if;
 return private.m1_prepare_v4(p_issue,p_input,p_policy,p_catalog)||jsonb_build_object('_issue_id',p_issue);
end$$;
create or replace function public.m1_publish_draft(p_issue uuid,p_expected_revision bigint,p_issue_revision bigint,p_policy bigint,p_catalog bigint,p_effect_key text) returns jsonb language plpgsql security definer set search_path='' as $$
begin perform private.m1_assert_editor();perform 1 from private.issues where id=p_issue for update;
 return private.m1_publish_draft_v1(p_issue,p_expected_revision,p_issue_revision,p_policy,p_catalog,p_effect_key);
end$$;
alter function private.m1_current_evidence(uuid) rename to m1_current_evidence_v2;
create function private.m1_current_evidence(p_issue uuid) returns boolean language sql stable set search_path='' as $$
 select private.m1_current_evidence_v2(p_issue) and exists(select 1 from private.issues i join private.article_versions v on v.id=i.current_version_id
 where i.id=p_issue and private.m1_core_evidence(i.id,v.public_body->>'article_kind'))
$$;
create function private.m1_body_issue(p_body jsonb) returns uuid language sql stable set search_path='' as $$
 select coalesce(nullif(p_body->>'_issue_id','')::uuid,(select c.issue_id from jsonb_array_elements(coalesce(p_body->'impacts','[]')) x
 cross join lateral jsonb_array_elements_text(coalesce(x->'evidence_ids','[]')) e(id)
 join private.claims c on c.id=e.id::uuid limit 1))
$$;
create function private.m1_live_schedule(p_body jsonb,p_now timestamptz) returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(case when x->>'kind'='EXACT' then jsonb_build_object('kind','EXACT','title',x->>'title','event_at',x->>'event_at','timezone',x->>'timezone')
 else jsonb_strip_nulls(jsonb_build_object('kind','PERIOD','title',x->>'title','period_label',x->>'period_label','date_note',case when x->>'precision'='DATE_RANGE' then null else '정확한 날짜 미정' end,'timezone',x->>'timezone')) end),'[]')
 from jsonb_array_elements(coalesce(p_body->'schedule','[]')) x
 where case when x->>'status'<>'VERIFIED' then false
 when x->>'kind'='EXACT' then (x->>'event_at')::timestamptz>p_now
 when x->>'kind'='PERIOD' then (x->>'period_end')::timestamptz>p_now else false end
 and jsonb_array_length(coalesce(x->'evidence_ids','[]'))>0
 and not exists(select 1 from jsonb_array_elements_text(x->'evidence_ids') e(id)
 where not private.m1_claim_allowed(e.id::uuid,private.m1_body_issue(p_body),false,true))
$$;
create or replace function private.visible_sections(p_profile text,p_body jsonb,p_as_of timestamptz,p_now timestamptz) returns text[] language plpgsql stable set search_path='' as $$
declare r text[]:=array['KEY_ISSUES','ISSUE_ANALYSIS'];
begin
 if p_body->>'_contract' is distinct from 'M1' then return private.m0_visible_sections(p_profile,p_body,p_as_of,p_now);end if;
 if p_profile is distinct from p_body->>'_profile' then raise exception 'SCENARIO_PATH_MISMATCH';end if;
 if jsonb_array_length(p_body->'_positive_paths')>0 then r:=array_append(r,'SCENARIOS');end if;
 if jsonb_array_length(p_body->'benefit_sector_ids')>0 then r:=array_append(r,'BENEFIT_SECTORS');end if;
 if jsonb_array_length(p_body->'damage_sector_ids')>0 then r:=array_append(r,'DAMAGE_SECTORS');end if;
 if jsonb_array_length(p_body->'related_sector_ids')>0 then r:=array_append(r,'RELATED_SECTORS');end if;
 if jsonb_array_length(p_body->'risks')>0 then r:=array_append(r,'RISKS');end if;
 if jsonb_array_length(private.m1_live_schedule(p_body,greatest(p_as_of,p_now)))>0 then r:=array_append(r,'SCHEDULE');end if;
 return array_append(r,'SOURCES');
end$$;
create or replace function private.public_body(p_body jsonb,p_sections text[],p_now timestamptz) returns jsonb language plpgsql stable set search_path='' as $$
declare r jsonb;impact jsonb;items jsonb:='[]';name text;
begin
 if p_body->>'_contract' is distinct from 'M1' then return private.m0_public_body(p_body,p_sections,p_now);end if;
 r:=jsonb_build_object('key_issues',p_body->'key_issues','issue_analysis',p_body->>'issue_analysis',
 'sources',(select coalesce(jsonb_agg(jsonb_build_object('name',x->>'name','url',x->>'url')),'[]') from jsonb_array_elements(p_body->'sources') x),
 'visible_sections',p_sections,'source_market',p_body->>'source_market','selection_market_basis',p_body->>'selection_market_basis','analysis_perspective','KR_EQUITY','impact_profile',p_body->>'_profile','article_kind',p_body->>'article_kind');
 for impact in select value from jsonb_array_elements(p_body->'impacts') loop
  select s.name into name from private.sectors s where s.id=(impact->>'sector_id')::uuid and s.active;
  if found then items:=items||jsonb_build_array(jsonb_build_object('sector_id',impact->>'sector_id','sector_name',name,'path_id',impact->>'path_id','direction',impact->>'direction','conditional_direction',impact->>'conditional_direction','description',impact->>'description','conditions',impact->'conditions'));end if;
 end loop;
 r:=r||jsonb_build_object('impacts',items);
 if 'SCENARIOS'=any(p_sections) then r:=r||jsonb_build_object('scenarios',(select jsonb_agg(jsonb_build_object('direction',x->>'direction','title',x->>'title','expected_result',x->>'expected_result','checks',x->'checks','path_ids',x->'path_ids')) from jsonb_array_elements(p_body->'scenarios') x));end if;
 if 'RISKS'=any(p_sections) then r:=r||jsonb_build_object('risks',p_body->'risks');end if;
 if 'SCHEDULE'=any(p_sections) then r:=r||jsonb_build_object('schedule',private.m1_live_schedule(p_body,p_now));end if;
 return r;
end$$;
create function public.m1_operation_status(p_issue uuid,p_effect_key text) returns jsonb language plpgsql security definer set search_path='' as $$
declare o private.outbox;
begin perform private.m1_assert_editor();
 if p_issue is null or p_effect_key is null or length(p_effect_key) not between 1 and 200 then raise exception 'INVALID_OPERATION_KEY';end if;
 select * into o from private.outbox where issue_id=p_issue and effect_key=p_effect_key;
 if found then return jsonb_build_object('state','APPLIED','event_type',o.event_type,'version_id',o.version_id);end if;
 -- Absence is not proof that an uncertain request cannot still arrive.
 return jsonb_build_object('state','UNKNOWN');
end$$;$c05d_source$;
for rec in select cl.oid,ns.nspname,cl.relname from pg_class cl join pg_namespace ns on ns.oid=cl.relnamespace where ns.nspname='private' and cl.relname in ('admin_memberships','admin_sessions','editor_drafts') loop
 execute format('alter table %I.%I force row level security',rec.nspname,rec.relname);
 execute format('revoke all on table %I.%I from public,anon,authenticated,service_role',rec.nspname,rec.relname);
end loop;
for rec in select p.oid,p.oid::regprocedure::text as sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname||'.'||p.proname=any(array['private.active_admin_user','private.assert_editor','private.assert_initialized','private.assert_installation','private.assert_server','private.caller_role','private.is_admin','private.m0_get_public_article_legacy','private.m0_public_body','private.m0_publish_legacy','private.m0_visible_sections','private.m1_assert_editor','private.m1_body_issue','private.m1_claim_allowed','private.m1_core_evidence','private.m1_current_evidence','private.m1_current_evidence_v1','private.m1_current_evidence_v2','private.m1_draft_shape','private.m1_independent_three','private.m1_live_schedule','private.m1_prepare','private.m1_prepare_v1','private.m1_prepare_v2','private.m1_prepare_v3','private.m1_prepare_v4','private.m1_publish_draft_v1','private.m1_save_draft_v1','private.m1_schedule','private.m1_text_array','private.public_body','private.sync_public_issue','private.visible_sections','public.get_public_article','public.is_news_visible','public.m0_ack','public.m0_admin_view_count','public.m0_claim','public.m0_create_installation','public.m0_enqueue','public.m0_enqueue_due','public.m0_fail','public.m0_get_settings','public.m0_heartbeat','public.m0_job_status','public.m0_mark_effect_intent','public.m0_pending_confirmation','public.m0_publish','public.m0_reconcile','public.m0_record_view','public.m0_requeue_dlq','public.m0_rotate_installation','public.m0_runtime_identity','public.m0_set_publication_state','public.m0_source_technical_result','public.m0_update_settings','public.m1_check_editor','public.m1_close_admin_session','public.m1_create_draft','public.m1_dispatch_outbox','public.m1_editor_articles','public.m1_editor_catalog','public.m1_get_draft','public.m1_open_admin_session','public.m1_operation_status','public.m1_preview_draft','public.m1_public_article','public.m1_public_articles','public.m1_public_catalog','public.m1_public_identity','public.m1_publish_draft','public.m1_read_admin_session','public.m1_save_draft','public.m1_set_state','public.resolve_issue']) loop
 execute 'revoke all on function '||rec.sig||' from public,anon,authenticated,service_role';
 if pg_get_userbyid((select proowner from pg_proc where oid=rec.oid))<>'postgres' then raise exception 'FUNCTION_OWNER';end if;
end loop;
current_meta:=jsonb_build_object('schemas',(select jsonb_agg(jsonb_build_array(nspname,pg_get_userbyid(nspowner),nspacl::text) order by nspname) from pg_namespace where nspname in ('private','judoju_control','public')),'relations',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,c.relkind,pg_get_userbyid(c.relowner),c.relacl::text,c.relrowsecurity,c.relforcerowsecurity,c.reloptions,case when c.relkind='v' then pg_get_viewdef(c.oid,true) else null end) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list')) and c.relkind in ('r','p','v','m','f','S')),'columns',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl::text,a.attcollation::regcollation::text,pg_get_expr(d.adbin,d.adrelid)) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list')) and a.attnum>0 and not a.attisdropped and c.relkind in ('r','p','v','m','f')),'constraints',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,x.conname,pg_get_constraintdef(x.oid,true)) order by n.nspname,c.relname,x.conname) from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname in ('private','judoju_control') or n.nspname='public' and c.relname in ('news_public','news_list'))),'indexes',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,pg_get_indexdef(i.indexrelid)) order by n.nspname,c.relname,pg_get_indexdef(i.indexrelid)) from pg_index i join pg_class c on c.oid=i.indrelid join pg_namespace n on n.oid=c.relnamespace where (n.nspname i