name) from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('private','judoju_control','public')),'defaults',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(d.defaclrole),coalesce(n.nspname,'GLOBAL'),d.defaclobjtype,d.defaclacl::text) order by pg_get_userbyid(d.defaclrole),coalesce(n.nspname,'GLOBAL'),d.defaclobjtype) from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where d.defaclnamespace=0 or n.nspname in ('private','judoju_control','public')),'roles',(select jsonb_agg(jsonb_build_array(rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,rolreplication,rolconnlimit,rolvaliduntil,rolbypassrls,md5(coalesce(rolconfig::text,''))) order by rolname) from pg_roles),'memberships',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(roleid),pg_get_userbyid(member),pg_get_userbyid(grantor),admin_option,inherit_option,set_option) order by roleid,member,grantor) from pg_auth_members),'database_role_settings',(select jsonb_agg(jsonb_build_array(setdatabase,pg_get_userbyid(setrole),md5(setconfig::text)) order by setdatabase,setrole) from pg_db_role_setting where setdatabase=0 or setdatabase=(select oid from pg_database where datname=current_database())),'ddl_event_triggers',(select jsonb_agg(jsonb_build_array(e.evtname,e.evtevent,e.evtenabled,e.evttags,pg_get_userbyid(e.evtowner),n.nspname,p.proname,md5(pg_get_functiondef(p.oid))) order by e.evtname) from pg_event_trigger e join pg_proc p on p.oid=e.evtfoid join pg_namespace n on n.oid=p.pronamespace),'data',(select jsonb_agg(to_jsonb(r) order by relation) from (select 'judoju_control.environment_identity' as relation,count(*) as count,encode(extensions.digest(convert_to(coalesce(string_agg(to_jsonb(t)::text,E'\n' order by to_jsonb(t)::text),''),'UTF8'),'sha256'),'hex') as digest from judoju_control.environment_identity t union all select 'judoju_control.schema_artifacts' as relation,count(*) as count,encode(extensions.dig