'managed_columns',(select jsonb_agg(jsonb_build_array(cl.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl::text) order by cl.relname collate "C",a.attnum) from pg_attribute a join pg_class cl on cl.oid=a.attrelid join pg_namespace n on n.oid=cl.relnamespace where n.nspname='auth' and cl.relname in ('users','sessions') and a.attnum>0 and not a.attisdropped),
'managed_policies',(select jsonb_agg(jsonb_build_array(cl.relname,pol.polname,pol.polpermissive,pol.polcmd,pol.polroles::text,pg_get_expr(pol.polqual,pol.polrelid),pg_get_expr(pol.polwithcheck,pol.polrelid)) order by cl.relname collate "C",pol.polname collate "C") from pg_policy pol join pg_class cl on cl.oid=pol.polrelid join pg_namespace n on n.oid=cl.relnamespace where n.nspname='auth' and cl.relname in ('users','sessions')),
'noninternal_triggers',(select jsonb_agg(jsonb_build_array(cl.relname,t.tgname,t.tgenabled,t.tgtype,fn.nspname,p.proname) order by cl.relname collate "C",t.tgname collate "C") from pg_trigger t join pg_class cl on cl.oid=t.tgrelid join pg_namespace n on n.oid=cl.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace fn on fn.oid=p.pronamespace where n.nspname='auth' and cl.relname in ('users','sessions') and not t.tgisinternal),
'internal_ri_triggers',(select jsonb_agg(jsonb_build_array(target.relname,refns.nspname,ref.relname,x.conname,pg_get_constraintdef(x.oid),p.proname,t.tgtype,t.tgenabled) order by target.relname collate "C",refns.nspname collate "C",ref.relname collate "C",x.conname collate "C",p.proname collate "C",t.tgtype) from pg_trigger t join pg_class target on target.oid=t.tgrelid join pg_namespace targetns on targetns.oid=target.relnamespace join pg_constraint x on x.oid=t.tgconstraint join pg_class ref on ref.oid=x.conrelid join pg_namespace refns on refns.oid=ref.relnamespace join pg_proc p on p.oid=t.tgfoid where targetns.nspname='auth' and target.relname in ('users','sessions') and t.tgisinternal and x.contype='f' and x.confrelid=target.oid)
);
